rows as (
  select p.registry_id, p.source_key, p.source_seq, p.source_key_basis, p.status, p.record_kind,
         p.zip, p.last_seen_at, p.created_at, regexp_replace(p.source_key, '^.*:', '') as case_tail
    from public.app_projects p
   where p.registry_id in ('kcmo-building-permits','minneapolis-ccs-permits')
      or p.source_key like 'socrata:data.kcmo.org:w8jz-wjgn:%'
),
j as (
  select h.registry_id as h_reg, h.case_no, h.old_key, h.old_seq, r.*
    from held h left join rows r on r.case_tail = h.case_no
),
m as (
  select h_reg as registry_id, case_no, old_key, old_seq,
    count(*) filter (where source_key = old_key and source_seq = old_seq) as exact_n,
    count(*) filter (where source_key = old_key and source_seq <> old_seq) as other_seq_n,
    count(*) filter (where source_key <> old_key) as other_key_n,
    min(source_key||'|'||source_seq) filter (where source_key <> old_key) as other_key_sample,
    min(source_seq) filter (where source_key = old_key) as seq_now_min,
    max(source_seq) filter (where source_key = old_key) as seq_now_max,
    string_agg(distinct coalesce(status,'-')||'/'||coalesce(record_kind,'-')||'/zip:'||(zip is not null)::text||'/seen:'||coalesce(last_seen_at::date::text,'-'), ',') filter (where source_key = old_key) as exact_shape
  from j group by 1,2,3,4
)
select json_build_object(
  'source_summary', (select json_agg(x) from (
      select registry_id, split_part(source_key,':',1) as key_platform, source_key_basis, source_seq,
             count(*) as n, min(created_at)::date as first_created, max(created_at)::date as last_created,
             min(last_seen_at)::date as min_seen, max(last_seen_at)::date as max_seen
        from rows group by 1,2,3,4 order by 1,2,3,4) x),
  'held_match', (select json_agg(x) from (
      select registry_id,
             case when exact_n>0 then 'same_key_same_seq' when other_seq_n>0 then 'same_key_other_seq'
                  when other_key_n>0 then 'case_under_other_key' else 'absent' end as outcome,
             count(*) as n, min(other_key_sample) as other_key_sample, max(other_key_sample) as other_key_sample2,
             min(seq_now_min) as seq_min, max(seq_now_max) as seq_max
        from m group by 1,2 order by 1,2) x),
  'exact_shapes', (select json_agg(x) from (
      select registry_id, exact_shape, count(*) as n from m where exact_n+other_seq_n>0 group by 1,2 order by 3 desc limit 25) x),
  'absent_sample', (select json_agg(x) from (
      select registry_id, case_no from m where exact_n=0 and other_seq_n=0 and other_key_n=0 order by 1,2 limit 15) x),
  'dupe_keys', (select count(*) from (select source_key, source_seq from rows group by 1,2 having count(*)>1) d)
) as result;
